<?php require_once 'includes/config.php'; $pdo=db(); if(!isset($_SESSION['cart']))$_SESSION['cart']=[]; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';$id=(int)($_POST['product_id']??0); if($action==='add'){$qty=max(1,(int)($_POST['qty']??1));$st=$pdo->prepare('SELECT stock FROM products WHERE id=? AND status=1');$st->execute([$id]);$row=$st->fetch();if($row){$_SESSION['cart'][$id]=min($row['stock'],($_SESSION['cart'][$id]??0)+$qty);flash('success','Product added to cart.');}}elseif($action==='remove'){unset($_SESSION['cart'][$id]);flash('success','Item removed.');}elseif($action==='update'){foreach(($_POST['qtys']??[]) as $pid=>$qty){$pid=(int)$pid;$qty=(int)$qty;if($qty<=0){unset($_SESSION['cart'][$pid]);continue;}$st=$pdo->prepare('SELECT stock FROM products WHERE id=?');$st->execute([$pid]);$row=$st->fetch();if($row)$_SESSION['cart'][$pid]=min($row['stock'],$qty);}flash('success','Cart updated.');}redirect('cart.php');}
$items=[];$subtotal=0;if($_SESSION['cart']){$ids=array_keys($_SESSION['cart']);$ph=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT * FROM products WHERE id IN ($ph)");$st->execute($ids);foreach($st as $p){$p['qty']=$_SESSION['cart'][$p['id']];$p['line']=$p['qty']*$p['price'];$subtotal+=$p['line'];$items[]=$p;}}$title='Cart';require 'includes/header.php'; ?>
<h1 class="section-title">Shopping Cart</h1><?php if(!$items): ?><div class="bg-white border rounded-4 p-5 text-center"><i class="bi bi-cart-x display-3 text-purple"></i><h3 class="mt-3">Your cart is empty</h3><a class="btn btn-purple" href="products.php">Start Shopping</a></div><?php else: ?><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="update"><div class="row g-4"><div class="col-lg-8"><?php foreach($items as $it): ?><div class="bg-white border rounded-4 p-3 mb-3"><div class="row align-items-center"><div class="col-3"><img src="<?= e($it['image']) ?>" class="img-fluid" style="height:100px;object-fit:contain"></div><div class="col-5"><a class="text-decoration-none text-dark fw-semibold" href="product.php?id=<?= $it['id'] ?>"><?= e($it['name']) ?></a><div class="text-purple fw-bold">₹<?= number_format($it['price'],2) ?></div></div><div class="col-3"><input class="form-control" type="number" name="qtys[<?= $it['id'] ?>]" value="<?= $it['qty'] ?>" min="0" max="<?= $it['stock'] ?>"></div><div class="col-1"><button name="action" value="remove" class="btn btn-link text-danger" formaction="cart.php" formmethod="post" onclick="this.form.querySelector('[name=product_id]').value='<?= $it['id'] ?>'"><i class="bi bi-trash"></i></button></div></div></div><?php endforeach; ?><input type="hidden" name="product_id" value=""><button class="btn btn-outline-purple">Update Cart</button></div><div class="col-lg-4"><div class="bg-white border rounded-4 p-4"><h4>Summary</h4><div class="d-flex justify-content-between"><span>Subtotal</span><strong>₹<?= number_format($subtotal,2) ?></strong></div><div class="d-flex justify-content-between"><span>Shipping</span><span>Free</span></div><hr><div class="d-flex justify-content-between fs-5"><strong>Total</strong><strong class="text-purple">₹<?= number_format($subtotal,2) ?></strong></div><a href="checkout.php" class="btn btn-purple w-100 mt-3">Proceed to Checkout</a></div></div></div></form><?php endif; ?><?php require 'includes/footer.php'; ?>
